syntax:
Multiple function declarations with the same name but differing parameter types (including `const`-qualified parameters).  Member functions should be declared `const` if they don't modify the object's state.

Example:
```c++
class MyClass {
public:
  void myFunction(int x) { /* Modifies object state */ }
  void myFunction(int x) const { /* Does not modify object state */ }
};
```

code_example:
#include <iostream>
#include <string>
std::string shorterString(const std::string& s1, const std::string& s2) {
  return s1.length() <= s2.length() ? s1 : s2;
}
std::string shorterString(std::string& s1, std::string& s2) {
  //Could modify s1 or s2 here if needed.  But in this example, we don't need to
  return s1.length() <= s2.length() ? s1 : s2;
}
int main() {
  std::string str1 = "hello";
  std::string str2 = "world";
  std::string result1 = shorterString(str1, str2); // Calls the non-const version if available; otherwise const version.
  const std::string str3 = "test";
  const std::string str4 = "example";
  std::string result2 = shorterString(str3, str4); // Calls the const version only.
  std::cout << result1 << "\n" << result2 << std::endl;
  return 0;
}
